    // Exiting the loop means i+2 ≥ n, and from the invariant we know
    // no triple occurred at any j < i; but `j+2 < n` ⇒ `j < n-2` ≤ i,
    // so no triple anywhere.  We re­assert this to help the verifier.
    assert!(
        forall(|j: usize| j + 2 < n ==>
            !(a[j] == a[j+1] && a[j+1] == a[j+2])
        )
    );

